const RailService=(()=>{
let stationBlockedUntil=0;
const normalize=s=>String(s||'').trim().replace(/(站|駅)$/,'');
function candidates(data,name){if(!Array.isArray(data))throw Error('车站索引响应无效');const target=normalize(StationMatch.aliases[name]||name);return data.filter(r=>/^(station|halt|tram_stop)$/.test(r.railway||'')&&Object.keys(r).filter(k=>k==='name'||k.startsWith('name:')||k==='uic_name').some(k=>normalize(r[k])===target)).map(r=>({name:r.name,operator:[r.operator,r['operator:en'],r.network].filter(Boolean).join(' / '),xy:[Number(r.latitude),Number(r.longitude)],tags:r,osmId:r.osm_id})).filter(r=>r.xy.every(Number.isFinite)&&Math.abs(r.xy[0])<=85&&Math.abs(r.xy[1])<=180)}
async function station(name,signal){const query=StationMatch.aliases[name]||name,key='orm-station:v1:'+query;const hit=await Services.read(key,30*86400000);if(hit)return hit;if(Date.now()<stationBlockedUntil)throw Error('铁路车站索引暂时限流，请稍后再试');try{const data=await Services.json('https://api.openrailwaymap.org/v2/facility?'+new URLSearchParams({name:query,limit:'50'}),{signal,timeout:5000});const result=candidates(data,name);if(!result.length)throw Error('铁路索引未找到精确车站：'+name);await Services.write(key,result);return result}catch(e){if(/429/.test(e.message))stationBlockedUntil=Date.now()+3600000;else if(!signal?.aborted&&/HTTP|超时|fetch/i.test(e.message))stationBlockedUntil=Date.now()+15000;throw e}}
async function locate(names,trip,signal,progress){const points=[];for(const name of names){if(signal?.aborted)throw Error('已停止');progress?.('铁路站点索引：'+name);const point=trip.overrides?.[name]||StationMatch.rank(await station(name,signal),name,trip)[0].xy;points.push(point);trip._lastPoint=point}return points}
function validate(data,points){const feature=data?.features?.find(f=>f.geometry?.type==='LineString'),coords=feature?.geometry?.coordinates;if(!coords||coords.length<3)throw Error('铁路寻路没有返回有效轨道几何');const path=coords.map(c=>[c[1],c[0]]);if(path.some(p=>!p.every(Number.isFinite)||Math.abs(p[0])>85||Math.abs(p[1])>180))throw Error('铁路路径坐标无效');const rows=feature.properties?.messages,index=rows?.[0]?.indexOf('WayTags');if(index==null||index<0||rows.length<2)throw Error('铁路寻路缺少轨道标签，未采用此结果');for(const row of rows.slice(1)){const tags=String(row[index]||'');if(!/(?:^|\s)railway=(rail|light_rail|narrow_gauge|tram|subway)(?:\s|$)/.test(tags))throw Error('路径包含非铁路段，已拒绝作为铁路轨迹')}
if(Core.km(points[0],path[0])>1||Core.km(points.at(-1),path.at(-1))>1)throw Error('铁路吸附点偏离车站超过 1 km');for(const p of points)if(!path.some(q=>Core.km(p,q)<1))throw Error('铁路路径未经过指定途经站');return path}
const mainlineProfile='---context:global\nassign continueStraight false\nassign downhillcost 0\nassign uphillcost 0\n---context:way\nassign turncost 0\nassign initialcost 0\nassign costfactor switch railway=rail 1 100000\n---context:node\nassign initialcost 0\n';
async function profileId(signal,renew=false){if(!renew)return await Services.read('mainline-profile:v1')||'custom_1795737045785';const result=await Services.json('https://brouter.de/brouter/profile',{signal,method:'POST',headers:{'Content-Type':'text/plain'},body:mainlineProfile,timeout:12000});if(result.error||!/^custom_\d+$/.test(result.profileid||''))throw Error('国铁寻路规则加载失败');return Services.write('mainline-profile:v1',result.profileid)}
function merge(full,leg,station){if(!full.length)return leg.slice();const key=p=>p[0]+','+p[1];if(key(full.at(-1))===key(leg[0]))return full.concat(leg.slice(1));const near=new Map();for(let i=0;i<leg.length;i++)if(Core.km(leg[i],station)<1)near.set(key(leg[i]),i);for(let i=full.length-1;i>=0;i--)if(Core.km(full[i],station)<1&&near.has(key(full[i])))return full.slice(0,i+1).concat(leg.slice(near.get(key(full[i]))+1));throw Error('途经站两侧轨道未连接，未用直线拼接；请核对站台或途经线路')}
async function route(points,signal,progress,trip={}){if(points.length<2)throw Error('至少需要两个铁路站点');const mainline=StationMatch.context(trip).label==='国铁';let profile=mainline?await profileId(signal):'rail',full=[];
 for(let i=1;i<points.length;i++){if(signal?.aborted)throw Error('已停止');if(Core.km(points[i-1],points[i])<.001)continue;progress?.('铁路分段寻路 '+i+'/'+(points.length-1)+(mainline?' · 国铁轨道':' · 城市铁路'));const pair=[points[i-1],points[i]],key='rail-leg:v2:'+(mainline?'mainline':'mixed')+':'+JSON.stringify(pair);let leg=await Services.read(key,30*86400000);
 if(!leg){const request=()=>Services.json('https://brouter.de/brouter?'+new URLSearchParams({lonlats:pair.map(p=>p[1]+','+p[0]).join('|'),profile,alternativeidx:'0',format:'geojson'}),{signal,timeout:45000});let data;try{data=await request()}catch(e){if(mainline&&[400,404,500].includes(e.status)&&/profile.*(not found|does not exist|unknown)|FileNotFound/i.test(e.detail||'')){profile=await profileId(signal,true);data=await request()}else{if(e.status===400&&/no track found/i.test(e.detail||''))e.message+='；该站间轨道未连通或吸附位置不正确';throw e}}leg=validate(data,pair);if(mainline){const rows=data.features.find(f=>f.geometry?.type==='LineString').properties.messages,index=rows[0].indexOf('WayTags');if(rows.slice(1).some(r=>!/(?:^|\s)railway=rail(?:\s|$)/.test(r[index])))throw Error('国铁结果混入其他轨道，未采用')}await Services.write(key,leg)}
 full=merge(full,leg,points[i-1]);
 }if(full.length<3)throw Error('铁路路径为空');for(const p of points)if(!full.some(q=>Core.km(p,q)<1))throw Error('拼接路径未经过指定停站');return full;
}
return{locate,route,validate,candidates,merge};})();
if(typeof module!=='undefined')module.exports=RailService;
